 const target=boundary==='state'?"BEFORE UPDATE ON tower_autonomy_cycles WHEN OLD.state='thinking' AND NEW.state='execute'":boundary==='authorization'?"BEFORE INSERT ON tower_autonomy_authorizations":boundary==='anchor'?"BEFORE INSERT ON tower_autonomy_task_anchors":`BEFORE INSERT ON tower_autonomy_events WHEN NEW.kind='${boundary==='action-audit'?'action-authorized':'state-transition'}'`;
