const privateMarker='PRIVATE_PROVIDER_PROMPT_MODEL_PRODUCER';
function pngChunk(type:string,data:Uint8Array){const result=Buffer.alloc(data.length+12);result.writeUInt32BE(data.length);result.write(type,4);result.set(data,8);let crc=0xffffffff;for(const byte of result.subarray(4,-4)){crc^=byte;for(let i=0;i<8;i++)crc=crc&1?0xedb88320^(crc>>>1):crc>>>1;}result.writeUInt32BE((crc^0xffffffff)>>>0,result.length-4);return result;}
function privatePNG(input:Buffer,trailing=false){const chunks:Buffer[]=[input.subarray(0,8)];let inserted=false;for(let at=8;at<input.length;){const length=input.readUInt32BE(at),type=input.toString('ascii',at+4,at+8),end=at+length+12;if(type==='IDAT'&&!inserted){for(const name of ['tEXt','iTXt','zTXt','eXIf'])chunks.push(pngChunk(name,Buffer.from(privateMarker+'\0'+name)));chunks.push(pngChunk('IDAT',Buffer.concat([input.subarray(at+8,at+8+length),...(trailing?[Buffer.from(privateMarker+' compressed-trailing')]:[])])));inserted=true;}else chunks.push(input.subarray(at,end));at=end;}return Buffer.concat(chunks);}
test('provider prompt/model ancillary metadata never enters public R2 or visual audit and pixels are preserved',async()=>{
 const db=database(),storage=memoryBucket(),provider=syntheticProvider({privateMetadata:true});try{const manager=createManagerAutonomy({db,now:clock,bucket:storage,apiKey:'synthetic',transport:provider.transport,wake:async()=>{},assetFetch:async()=>new Response(new Uint8Array(200))});await manager.enable();for(let i=0;i<12;i++)await manager.step();const state=await manager.publicState();assert.ok(state);for(const [scene,colour] of [['day',21],['night',22]] as const){const publicBytes=await manager.asset(state.generation,scene);assert.ok(publicBytes);const bytes=Buffer.from(publicBytes);assert.equal(bytes.includes(Buffer.from(privateMarker)),false);assert.deepEqual(PNG.sync.read(bytes).data,PNG.sync.read(image(colour)).data);const types:string[]=[];for(let at=8;at<bytes.length;at+=bytes.readUInt32BE(at)+12)types.push(bytes.toString('ascii',at+4,at+8));assert.deepEqual(types,['IHDR','IDAT','IEND']);}
 for(const stored of storage.data.values())assert.equal(Buffer.from(stored).includes(Buffer.from(privateMarker)),false);assert.doesNotMatch(JSON.stringify(state),/PRIVATE_PROVIDER|prompt|producer|muse-image/);
 const audit=provider.requests.find(request=>String(request.payload.instructions).includes('You are an independent TaskAudit reviewer')&&!request.url.endsWith('/input_tokens'))!;for(const message of audit.payload.input as {content:{type:string;image_url?:string}[]}[])for(const part of message.content)if(part.type==='input_image'&&part.image_url?.startsWith('data:image/png'))assert.equal(Buffer.from(part.image_url.split(',')[1],'base64').includes(Buffer.from(privateMarker)),false);
 assert.doesNotMatch(readFileSync(new URL('../src/live/tower-appearance.ts',import.meta.url),'utf8'),/PRIVATE_PROVIDER|Fang content/);
 }finally{db.close();}
});
